with open(p,'w') as f: f.write('def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {v: sum(cell == v for row in grid for cell in row) for row in grid for v in row}
    bg = max(counts, key=counts.get)
    first = min(r for r, row in enumerate(grid) if any(v != bg for v in row))
    if first >= h / 2:
        return [row[:] for row in grid]
    out = [[bg for _ in range(w)] for _ in range(h)]
    for r in range(h - 1):
        for c in range(w):
            if grid[r][c] != bg:
                out[r + 1][c] = grid[r][c]
    return out
')
